(function(){
  function cls(n){ return Java.loadClass(n); }
  function consumer(){ return new JavaAdapter(cls("java.util.function.Consumer"), { accept: function(v){} }); }
  var BR = cls("net.minecraft.core.registries.BuiltInRegistries");
  var RL = cls("net.minecraft.resources.ResourceLocation");
  var S = cls("net.minecraft.world.item.ItemStack");
  var CCM = cls("com.merlinkitsune.astral_dice.choice.CardChoiceManager");
  var CCT = cls("com.merlinkitsune.astral_dice.choice.CardChoiceType");
  var player = AutoJS.players()[0];
  var out = {};
  player.closeContainer();
  out.hasOpenBefore = CCM.hasOpenSession(player);
  var type0 = CCT.valueOf("ANY");
  out.rejectTwo = Number(CCM.start(player, 2, type0, consumer()));
  out.hasOpenAfterReject = CCM.hasOpenSession(player);
  var token = Number(CCM.start(player, 3, type0, consumer()));
  out.token = token;
  out.tokenPositive = token > 0;
  var menu = player.containerMenu;
  out.menuClass = String(menu);
  out.menuIsCardChoice = out.menuClass.indexOf("CardChoiceMenu") >= 0;
  if (!out.menuIsCardChoice) { out.abort = true; return out; }
  out.abort = false;
  out.slotCount = Number(menu.slotCount());
  out.typeName = String(menu.type().name());
  out.tokenMatches = Number(menu.token()) === token;
  out.slotsSize = Number(menu.slots.size());
  out.hiddenMaxStack = Number(menu.getSlot(0).getMaxStackSize());
  var card = new S(BR.ITEM.get(RL.parse("astral_dice:attack_card_medium")));
  var stone = new S(BR.ITEM.get(RL.parse("minecraft:diamond")));
  out.mayPlaceCard = menu.getSlot(0).mayPlace(card);
  out.mayPlaceDiamond = menu.getSlot(0).mayPlace(stone);
  for (var i = 0; i < 3; i++) {
    var st = new S(card.getItem());
    try { menu.getSlot(i).setByPlayer(st); } catch (e1) { menu.getSlot(i).set(st); }
  }
  out.filledOnFill = Number(menu.filledSlots());
  out.completeOnFill = menu.isComplete();
  for (var j = 0; j < 3; j++) {
    try { menu.getSlot(j).setByPlayer(S.EMPTY); } catch (e2) { menu.getSlot(j).set(S.EMPTY); }
  }
  out.filledAfterClear = Number(menu.filledSlots());
  return out;
})()

(function(){
  function cls(n){ return Java.loadClass(n); }
