(function(){
  function cls(n){ return Java.loadClass(n); }
  var CCM = cls("com.merlinkitsune.astral_dice.choice.CardChoiceManager");
  var player = AutoJS.players()[0];
  var out = {};
  var token = 0;
  var menu = player.containerMenu;
  if (String(menu).indexOf("CardChoiceMenu") >= 0) { token = Number(menu.token()); }
  out.closedToken = token;
  try { CCM.abandon(player, token); } catch (e) { out.abandonErr = String(e); }
  player.closeContainer();
  out.hasOpenAfterClose = CCM.hasOpenSession(player);
  out.menuAfterClass = String(player.containerMenu);
  return out;
})()
